"""POST /payments/refund -> payments-refund (blueprint S1).

Port of app.py:321-331 + payment.refund_payment. Public, no ownership check
(whoever knows the chargeId can refund). Missing chargeId key -> 400
{error: 'chargeId is required'}; falsy chargeId -> 400 {error: 'Invalid Charge
ID', type: 'ValueError'}. Simulation always answers 200 with a fresh
secrets.token_urlsafe(16) refundId -- no validation that the charge was ever
collected, no amount check. The only side effect: when the ledger row exists
(looked up by the type-annotated key, SI-8/D-8) its status flips to 'refunded'
in place; when it does not, nothing changes and the answer is still 200
(refund-validation-and-effect). The booking table is NOT touched; _refunds is
not migrated (GAP-6/D-8).
"""

import json
import os

import boto3

import storage
import payments

# global init: once per cold start; table names come from the environment
# injected by the template (D-11, GAP-22); no config.py / .env / STAGE suffixes
dynamodb = boto3.resource('dynamodb', region_name=os.environ.get('AWS_REGION', 'us-east-1'))


def _claims(event):
    """Identity handed over by the gateway authorizer (SI-6/SI-7): the business
    user id is claims.sub; nothing else is read from the token, no token code
    lives in the function (D-1: auth is infrastructure)."""
    authorizer = (event.get('requestContext') or {}).get('authorizer') or {}
    return authorizer.get('claims') or {}


def _cors_headers(event):
    """global_middleware[0] (flask-cors CORS(app), D-4/D-10, GM1): echo the
    request's Origin verbatim (Vary: Origin only then), otherwise '*'.
    Access-Control-Allow-Methods and Access-Control-Allow-Headers belong to
    the preflight (OPTIONS) path only -- the monolith's real responses never
    carried them; the gateway's Cors block answers OPTIONS."""
    origin = None
    for name, value in (event.get('headers') or {}).items():
        if isinstance(name, str) and name.lower() == 'origin':
            origin = value
            break
    headers = {'Content-Type': 'application/json'}
    if origin:
        headers['Access-Control-Allow-Origin'] = origin
        headers['Vary'] = 'Origin'
    else:
        headers['Access-Control-Allow-Origin'] = '*'
    if str(event.get('httpMethod') or '').upper() == 'OPTIONS':
        headers['Access-Control-Allow-Methods'] = 'DELETE, GET, HEAD, OPTIONS, PATCH, POST, PUT'
        headers['Access-Control-Allow-Headers'] = 'Content-Type, Authorization'
    return headers


def _json(status_code, payload, event):
    return {
        'statusCode': status_code,
        'headers': _cors_headers(event),
        'body': json.dumps(payload),
    }


def _parse_body(event):
    """request.get_json() stand-in: absent/empty body answers None (the routes
    turn that into their own 400); a malformed body raises, and the uniform
    exit answers it like the monolith's handler would (D-11.2)."""
    raw = event.get('body')
    if not raw:
        return None
    return json.loads(raw)

def _handle(event):
    data = _parse_body(event)
    if not data or 'chargeId' not in data:
        return _json(400, {'error': 'chargeId is required'}, event)
    result = payments.refund_payment(dynamodb, os.environ['PAYMENTS_TABLE'], data['chargeId'])
    return _json(200, result, event)


def lambda_handler(event, context):
    """Uniform exception exit replicated from app.py:28-36 (D-10/GAP-11):
    ValueError -> 400 {error, type}, anything else -> 500 {error, type};
    the CORS headers ride on the error responses too."""
    try:
        return _handle(event)
    except ValueError as e:
        return _json(400, {'error': str(e), 'type': 'ValueError'}, event)
    except Exception as e:
        return _json(500, {'error': str(e), 'type': type(e).__name__}, event)

return None


def _is_condition_failure(exc, dynamodb):
    """True when the write failed because its condition was not met.

    Real DynamoDB and DynamoDB Local raise ConditionalCheckFailedException for
    a failed ConditionExpression (monolith storage.py:155,178,243) and
    TransactionCanceledException for transactional conflicts; the blueprint
    keeps both outcomes distinct, so a TransactionCanceledException only
    counts as a condition miss when one of its reasons names
    ConditionalCheckFailed (a plain TransactionConflict never does)."""
    try:
        client = dynamodb.meta.client
        if isinstance(exc, client.exceptions.ConditionalCheckFailedException):
            return True
        if isinstance(exc, client.exceptions.TransactionCanceledException):
            reasons = _condition_reasons(exc)
            return True if reasons is None else any('Condition' in str(r) for r in reasons)
    except Exception:
        pass
    name = type(exc).__name__
    if name in ('ConditionalCheckFailedException', 'TransactionCanceledException'):
        if name == 'ConditionalCheckFailedException':
            return True
        reasons = _condition_reasons(exc)
        return True if reasons is None else any('Condition' in str(r) for r in reasons)
    return False


# --------------------------------------------------------------- flights

def get_flight(dynamodb, table_name, flight_id):
    """GetItem; any read failure is swallowed and answers None (monolith
    storage.py:115-124), so 'missing' and 'read failed' are indistinguishable."""
    try:
        response = dynamodb.Table(table_name).get_item(Key={'id': flight_id})
        if 'Item' in response:
            return to_python_obj(response['Item'])
        return None
    except Exception as e:
        print(f"Error getting flight {flight_id}: {str(e)}")
        return None


def get_flights_by_schedule(dynamodb, table_name, departure_code, arrival_code, departure_date):
    """Single Scan + three Attr().eq() filters, first page only (SI-4/GAP-3);
    a failing Scan degrades to [] (business_rules[3]), never 4xx/5xx."""
    try:
        response = dynamodb.Table(table_name).scan(
            FilterExpression=Attr('departureAirportCode').eq(departure_code)
                           & Attr('arrivalAirportCode').eq(arrival_code)
                           & Attr('departureDate').eq(departure_date)
        )
        items = response.get('Items', [])
        return [to_python_obj(item) for item in items]
    except Exception as e:
        print(f"Error searching flights: {str(e)}")
        return []


def reserve_flight_seat(dynamodb, table_name, flight_id):
    """One conditional decrement; no extra GetItem (blueprint flight-reserve)."""
    try:
        dynamodb.Table(table_name).update_item(
            Key={'id': flight_id},
            UpdateExpression='SET seatCapacity = seatCapacity - :dec',
            ConditionExpression='seatCapacity > :zero AND attribute_exists(id)',
            ExpressionAttributeValues={':dec': 1, ':zero': 0},
            ReturnValues='UPDATED_NEW',
        )
        return True
    except Exception as e:
        if _is_condition_failure(e, dynamodb):
            raise ValueError(f"Flight {flight_id} is fully booked or does not exist")
        raise ValueError(f"Failed to reserve seat: {str(e)}")


def release_flight_seat(dynamodb, table_name, flight_id):
    """Monolith GAP-18 two-step kept as-is: precondition read (swallowed into
    None -> 'does not exist' arm), then a conditional increment against the
    just-read maximumSeating; every non-condition failure is wrapped into
    'Failed to release seat: <原文>' (KeyError included) and the endpoint
    never answers 5xx."""
    try:
        flight = get_flight(dynamodb, table_name, flight_id)
        if not flight:
            raise ValueError(f"Flight {flight_id} does not exist")
        dynamodb.Table(table_name).update_item(
            Key={'id': flight_id},
            UpdateExpression='SET seatCapacity = seatCapacity + :inc',
            ConditionExpression='seatCapacity < :max',
            ExpressionAttributeValues={':inc': 1, ':max': flight['maximumSeating']},
            ReturnValues='UPDATED_NEW',
        )
        return True
    except Exception as e:
        if _is_condition_failure(e, dynamodb):
            raise ValueError("Cannot release seat, already at maximum capacity")
        raise ValueError(f"Failed to release seat: {str(e)}")


# -------------------------------------------------------------- bookings

def create_booking(dynamodb, table_name, booking_data):
    """PutItem the new booking (monolith storage.py:170-191): id=uuid4,
    checkedIn=False, paymentToken keeps the chargeId's JSON type
    (business_rules[12]), createdAt = naive local isoformat (D-14),
    bookingReference null."""
    booking_id = str(uuid.uuid4())
    booking = {
        'id': booking_id,
        'bookingOutboundFlightId': booking_data['outboundFlightId'],
        'checkedIn': False,
        'customer': booking_data['customerId'],
        'paymentToken': booking_data['chargeId'],
        'status': 'UNCONFIRMED',
        'createdAt': datetime.now().isoformat(),
        'bookingReference': None,
    }
    try:
        dynamodb.Table(table_name).put_item(Item=to_dynamodb_obj(booking))
        return to_python_obj(booking)
    except Exception as e:
        raise ValueError(f"Failed to create booking: {str(e)}")


def get_booking(dynamodb, table_name, booking_id):
    """GetItem with the read failure swallowed into None (monolith
    storage.py:194-202)."""
    try:
        response = dynamodb.Table(table_name).get_item(Key={'id': booking_id})
        if 'Item' in response:
            return to_python_obj(response['Item'])
        return None
    except Exception as e:
        print(f"Error getting booking {booking_id}: {str(e)}")
        return None


def update_booking_status(dynamodb, table_name, booking_id, status, booking_reference=None):
    """Conditional write 'attribute_exists(id)' (monolith storage.py:205-239):
    condition failed -> ValueError('Booking <id> not found'),
    any other failure -> ValueError('Failed to update booking: <原文>')."""
    try:
        update_expr = 'SET #status = :status'
        expr_attr_names = {'#status': 'status'}
        expr_attr_values = {':status': status}
        if booking_reference:
            update_expr += ', bookingReference = :ref'
            expr_attr_values[':ref'] = booking_reference
        response = dynamodb.Table(table_name).update_item(
            Key={'id': booking_id},
            UpdateExpression=update_expr,
            ExpressionAttributeNames=expr_attr_names,
            ExpressionAttributeValues=expr_attr_values,
            ConditionExpression='attribute_exists(id)',
            ReturnValues='ALL_NEW',
        )
        return to_python_obj(response['Attributes'])
    except Exception as e:
        if _is_condition_failure(e, dynamodb):
            raise ValueError(f"Booking {booking_id} not found")
        raise ValueError(f"Failed to update booking: {str(e)}")


def get_bookings_by_customer(dynamodb, table_name, customer_id, status=None):
    """Single Scan + Attr('customer').eq(), optional status equality layered
    on; first page only (SI-4), failure swallowed into [] (business_rules[4]).
    No sorting (SI-11/D-9)."""
    try:
        filter_expr = Attr('customer').eq(customer_id)
        if status:
            filter_expr = filter_expr & Attr('status').eq(status)
        response = dynamodb.Table(table_name).scan(FilterExpression=filter_expr)
        items = response.get('Items', [])
        return [to_python_obj(item) for item in items]
    except Exception as e:
        print(f"Error getting bookings for customer {customer_id}: {str(e)}")
        return []


# --------------------------------------------------------------- loyalty

def add_loyalty_points(dynamodb, table_name, customer_id, points):
    """One new ledger row per call, id = fresh uuid4 (business_rules[2][3]):
    NOT an accumulator update; repeated calls leave repeated rows."""
    loyalty_id = str(uuid.uuid4())
    loyalty_entry = {
        'id': loyalty_id,
        'customerId': customer_id,
        'points': points,
        'flag': 'active',
        'date': datetime.now().isoformat(),
    }
    try:
        dynamodb.Table(table_name).put_item(Item=to_dynamodb_obj(loyalty_entry))
        return to_python_obj(loyalty_entry)
    except Exception as e:
        raise ValueError(f"Failed to add loyalty points: {str(e)}")


def get_loyalty_points(dynamodb, table_name, customer_id):
    """Sum of int(item['points']) over first-page Scan rows matching
    customerId AND flag == 'active' strictly. Any conversion failure or a
    failed Scan degrades the whole total to 0 (SI-12), never 5xx."""
    try:
        response = dynamodb.Table(table_name).scan(
            FilterExpression=Attr('customerId').eq(customer_id) & Attr('flag').eq('active')
        )
        items = response.get('Items', [])
        total = 0
        for item in items:
            points = item.get('points', 0)
            total += int(points)
        return total
    except Exception as e:
        print(f"Error getting loyalty points for {customer_id}: {str(e)}")
        return 0


# ----------------------------------------------------------- user groups

def get_user_groups(dynamodb, table_name, sub):
    """Admin decision's data source (D-3, SI-13): the row's groups list, or []
    when the row is missing *or* the read fails -- never a 401 from here."""
    try:
        response = dynamodb.Table(table_name).get_item(Key={'sub': sub})
        if 'Item' in response:
            return response['Item'].get('groups', []) or []
        return []
    except Exception as e:
        print(f"Error getting user groups for {sub}: {str(e)}")
        return []


def is_admin(dynamodb, table_name, sub):
    """'Admin' in the stored groups (monolith auth.py:137 semantics)."""
    return 'Admin' in get_user_groups(dynamodb, table_name, sub)

